const L=s=>s.split(",").map(x=>x.trim()).filter(Boolean),KV=s=>L(s).map(x=>{const i=x.lastIndexOf(":");return i<0?[x,0]:[x.slice(0,i).trim(),x.slice(i+1).trim()]}),v=id=>$("#f_"+id).value;
let PW={for:null,m:{},changed:false};
function pcOpts(){const cs=L(($("#f_colors")||{}).value||(ed&&(ed.colors||[]).join(","))||"");return `<option value="*">All colours</option>`+cs.map(c=>`<option>${esc(c)}</option>`).join("")}
function renderPics(){const d=$("#pics");if(!d)return;d.innerHTML=Object.entries(PW.m).map(([c,a])=>`<div class="mu" style="margin-top:6px"><b>${esc(c)}</b></div><div class="thumbs">${a.map((u,i)=>`<span style="position:relative"><img src="${u}" alt=""><button class="btn r" style="position:absolute;top:-6px;right:-6px;padding:0 7px;border-radius:50%" onclick="rmPic('${esc(c)}',${i})">×</button></span>`).join("")}</div>`).join("")||`<p class="mu">No photos yet — placeholders are used.</p>`}
function rmPic(c,i){PW.m[c].splice(i,1);if(!PW.m[c].length)delete PW.m[c];PW.changed=true;renderPics()}
function shrink(f){return new Promise(res=>{const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,480/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);res(c.toDataURL("image/jpeg",.78))};im.src=r.result};r.readAsDataURL(f)})}
async function addPics(inp){const cs=L(v("colors")),sel=$("#f_pcol").value,keys=sel=="*"?(cs.length?cs:["Default"]):[sel];for(const f of inp.files){const u=await shrink(f);keys.forEach(k=>{(PW.m[k]=PW.m[k]||[]).push(u)})}PW.changed=true;inp.value="";renderPics()}
async function saveP(){const n=v("name").trim();if(!n)return alert("Name required");const id=ed.id||n.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"p"+Date.now();
 const o={id,name:n,brand:v("brand"),type:v("type"),desc:v("desc"),specs:Object.fromEntries(KV(v("specs"))),price:+v("price")||0,colors:L(v("colors")),storage:KV(v("storage")).map(([s,a])=>({s,add:+a||0})),cover:{on:$("#f_con").checked,price:+v("cprice")||0,colors:L(v("ccol"))},addons:KV(v("addons")).map(([n,p])=>({n,p:+p||0})),stock:$("#f_stock").checked};if(v("rel"))o.rel=v("rel");if(PW.for===ed&&(PW.changed||ed.pics))o.pics=PW.m;
 if(JSON.stringify(o).length>240000)return alert("Too many photos for one product — please remove a few.");
 await db.collection("products").doc(id).set(o);ed=null;await load();admin()}
async function tg(id){const p=P.find(x=>x.id==id);const{imgs,...q}=p;await db.collection("products").doc(id).set({...q,stock:p.stock===false});await load();admin()}
async function del(id){if(confirm("Delete this product?")){await db.collection("products").doc(id).delete();await load();admin()}}
async function seedDb(){for(const p of SEED)if(!P.some(x=>x.id==p.id&&x.fromDb)){const{imgs,...q}=p;await db.collection("products").doc(p.id).set(q)};await load();admin()}
async function load(){if(!db)return;try{const s=await db.collection("products").get();if(!s.empty)P=s.docs.map(d=>{const o={...d.data(),fromDb:1},q=SEED.find(x=>x.id==o.id);if(o.pics)o.imgs=o.pics;else if(q&&q.imgs)o.imgs=q.imgs;return o})}catch(e){}}
window.addEventListener("hashchange",()=>{const h=location.hash.slice(1)||"home";if(h=="home")track("view","home");else if(!h.startsWith("product-")&&h!==OWN)track("view",h);R()});
function safeR(){try{R()}catch(e){$("#app").innerHTML='<div class="panel"><h3>Something went wrong</h3><p class="mu">'+esc((e&&e.message)||e)+'</p><a class="btn" href="#home">Back to shop</a></div>'}}
safeR();
const tmo=(p,ms)=>Promise.race([p,new Promise((_,r)=>setTimeout(()=>r(new Error("timeout")),ms))]);
/* ====== Supabase connection (keys live in config.js) ====== */
const CFG=window.MAXI_CONFIG||{},SB=(CFG.SUPABASE_URL&&!CFG.SUPABASE_URL.includes("YOUR-")&&window.supabase)?window.supabase.createClient(CFG.SUPABASE_URL,CFG.SUPABASE_ANON_KEY):null;
if(SB)db={collection:n=>({
 get:async()=>{const r=await SB.from(n).select("*").order("created_at",{ascending:false}).limit(n=="events"?5000:1000);if(r.error)throw r.error;return{empty:!r.data.length,docs:r.data.map(x=>({data:()=>x.data}))}},
 doc:id=>({set:async o=>{const r=n=="products"?await SB.from(n).upsert({id,data:o}):await SB.from(n).insert({data:o});if(r.error)throw r.error},delete:async()=>{const r=await SB.from(n).delete().eq("id",id);if(r.error)throw r.error}})})};
function loginV(){return `<div class="panel" style="max-width:380px;margin:auto"><h3>Owner login</h3><label>Email</label><input id="le" type="email" autocomplete="username"><label>Password</label><input id="lp" type="password" autocomplete="current-password" onkeydown="if(event.key=='Enter')doLogin()"><p id="lerr" class="mu"></p><button class="btn" onclick="doLogin()">Log in</button> <a class="btn o" href="#home">Cancel</a></div>`}
async function doLogin(){const r=await SB.auth.signInWithPassword({email:$("#le").value.trim(),password:$("#lp").value});if(r.error){$("#lerr").textContent="Login failed: "+r.error.message;return}isOwner=true;admin()}
async function outAdmin(){try{await SB.auth.signOut()}catch(e){}isOwner=false;pinOk=false;location.hash="home"}
(async()=>{try{if(SB){const r=await SB.auth.getSession();isOwner=!!(r.data&&r.data.session)}}catch(e){}try{await tmo(load(),8000);track("view","home")}catch(e){}ready=true;safeR()})();
